// TOKEN 假设您在Go代码中定义了一个名为TOKEN的常量，用于存储您的令牌值
const TOKEN = "111"

func CheckSignature(ctx context.Context, c *app.RequestContext) {
	// 获取查询参数中的签名、时间戳和随机数
	signature := c.Query("signature")
	timestamp := c.Query("timestamp")
	nonce := c.Query("nonce")
	echostr := c.Query("echostr")
	// 创建包含令牌、时间戳和随机数的字符串切片
	tmpArr := []string{TOKEN, timestamp, nonce}
	// 对切片进行字典排序
	sort.Strings(tmpArr)
	// 将排序后的元素拼接成单个字符串
	tmpStr := ""
	for _, v := range tmpArr {
		tmpStr += v
	}
	// 对字符串进行SHA-1哈希计算
	tmpHash := sha1.New()
	tmpHash.Write([]byte(tmpStr))
	tmpStr = fmt.Sprintf("%x", tmpHash.Sum(nil))
	fmt.Println(tmpStr)
	fmt.Println(signature)
	// 将计算得到的签名与请求中提供的签名进行比较，并根据结果发送相应的响应
	if tmpStr == signature {
		c.String(200, echostr)
		//config.Rdb.Set(context.Background(), "library:token", tmpStr, 7*24*time.Hour)
	} else {
		c.String(403, "签名验证失败 "+timestamp)
	}
}
func WeChatLogin(ctx context.Context, c *app.RequestContext) {
	path := c.Query("url")
	state := utils2.RandString(5)                                               //防止跨站请求伪造攻击 增加安全性
	redirectURL := url.QueryEscape("https://" + path + "/v1/api/user/callback") //userinfo,
	wechatLoginURL := fmt.Sprintf("https://open.weixin.qq.com/connect/oauth2/authorize?appid=%s&redirect_uri=%s&response_type=code&state=%s&scope=snsapi_userinfo#wechat_redirect", "wx4e45463fb56f153b", redirectURL, state)
	wechatLoginURL, _ = url.QueryUnescape(wechatLoginURL)
	// 生成二维码
	qrCode, err := qrcode.Encode(wechatLoginURL, qrcode.Medium, 256)
	if err != nil {
		// 错误处理
		c.String(http.StatusInternalServerError, "Error generating QR code")
		return
	}
	// 将二维码图片作为响应返回给用户
	c.Header("Content-Type", "image/png")
	c.Write(qrCode)
}

func Callback(ctx context.Context, c *app.RequestContext) {
	// 获取微信返回的授权码
	code := c.Query("code")
	// 向微信服务器发送请求，获取access_token和openid
	tokenResp, err := http.Get(fmt.Sprintf("https://api.weixin.qq.com/sns/oauth2/access_token?appid=%s&secret=%s&code=%s&grant_type=authorization_code", "wx4e45463fb56f153b", "067316556da95a878a09762399661a14", code))
	if err != nil {
		fmt.Println(err)
		c.JSON(http.StatusBadRequest, gin.H{"code": code, "msg": err.Error()})
		return
	}
	// 解析响应中的access_token和openid
	var tokenData struct {
		AccessToken  string `json:"access_token"`
		ExpiresIn    int    `json:"expires_in"`
		RefreshToken string `json:"refresh_token"`
		OpenID       string `json:"openid"`
		Scope        string `json:"scope"`
	}
	if err1 := json.NewDecoder(tokenResp.Body).Decode(&tokenData); err1 != nil {

		c.JSON(http.StatusBadRequest, gin.H{"code": code, "msg": err1.Error()})
		return
	}
	userInfoURL := fmt.Sprintf("https://api.weixin.qq.com/sns/userinfo?access_token=%s&openid=%s", tokenData.AccessToken, tokenData.OpenID)
	userInfoResp, err := http.Get(userInfoURL)
	if err != nil {

		zap.L().Error("获取失败")
		return
	}
	defer userInfoResp.Body.Close()

	var userData struct {
		OpenID   string `json:"openid"`
		Nickname string `json:"nickname"`
	}
	if err1 := json.NewDecoder(userInfoResp.Body).Decode(&userData); err1 != nil {

		zap.L().Error("获取用户信息失败")
		return
	}

	auth := model.LxhAuth{
		AppName:    "微信",
		AppUnionid: userData.OpenID,
	}
	err = config.Db.Create(&auth).Error
	if err != nil {
		zap.L().Error("auth create err")
		return
	}
	marshal, _ := json.Marshal(userData)
	c.Write(marshal)
	zap.L().Info("登录成功")
	return
}

